import type { FitAddon } from "@xterm/addon-fit";
import type { SearchAddon } from "@xterm/addon-search";
import type { Terminal } from "@xterm/xterm";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "./tauri";
import { terminalEventBus } from "./terminalEvents";
import { attachWebglRenderer, loadTerminalAssets } from "./terminalRenderer";
import {
  applyTerminalSettings,
  FALLBACK_PREFERENCES,
  fetchCachedNativePreferences,
  loadTerminalSettings,
  resolveTerminalSettings,
  type EffectiveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type TerminalInstance = {
  element: HTMLDivElement;
  terminal: Terminal;
  fitAddon: FitAddon;
  searchAddon: SearchAddon;
  disposeWebgl: () => void;
  resizeObserver: ResizeObserver;
  disposables: Array<() => void>;
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  unsubscribeOutput?: () => void;
};

export const MAX_PENDING_OUTPUT_CHARS = 128 * 1024;

/**
 * Batches incoming PTY output chunks per terminal renderer at animation-frame cadence.
 *
 * Queue policy:
 * - Chunks received between rAF flushes are held in an ordered per-renderer buffer.
 * - On frame flush, all buffered chunks coalesce into a single `terminal.write` call in original arrival order.
 * - If queued characters reach or exceed `MAX_PENDING_OUTPUT_CHARS` before rAF, the buffer is flushed synchronously
 *   to guarantee memory safety without loss or reordering.
 * - Replay backlog delivered synchronously during `subscribeOutput` is enqueued before subsequent live output.
 * - Teardown (via unlisten or manager destroy) immediately cancels pending rAF callbacks and clears buffered data,
 *   preventing stale or out-of-order writes after session rebinding or instance disposal.
 */
function attachScheduledOutputSubscription(
  backendSessionId: string,
  terminal: Terminal,
): () => void {
  let outputBuffer: string[] = [];
  let outputBufferChars = 0;
  let outputFrame = 0;

  const flushOutput = () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    if (outputBuffer.length === 0) return;
    const coalesced = outputBuffer.length === 1 ? outputBuffer[0]! : outputBuffer.join("");
    outputBuffer = [];
    outputBufferChars = 0;
    terminal.write(coalesced);
  };

  const unsubscribe = terminalEventBus.subscribeOutput(backendSessionId, (text) => {
    outputBuffer.push(text);
    outputBufferChars += text.length;

    if (outputBufferChars >= MAX_PENDING_OUTPUT_CHARS) {
      flushOutput();
    } else if (outputFrame === 0) {
      outputFrame = requestAnimationFrame(flushOutput);
    }
  });

  return () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    outputBuffer = [];
    outputBufferChars = 0;
    unsubscribe();
  };
}

export const DEFAULT_WARM_CACHE_LIMIT = 2;

type SpawnGeneration = {
  generation: number;
  activeCount: number;
};

class TerminalHostManager {
  private instances = new Map<string, TerminalInstance>();
  private pendingSpawns = new Map<string, Promise<TerminalInstance>>();
  private spawnGenerations = new Map<string, SpawnGeneration>();
  private visibleRefCounts = new Map<string, number>();
  private inactiveLruSessionIds: string[] = [];
  private warmCacheLimit = DEFAULT_WARM_CACHE_LIMIT;

  setWarmCacheLimit(limit: number): void {
    this.warmCacheLimit = Math.max(0, limit);
    this.evictInactiveIfNeeded();
  }

  getWarmCacheLimit(): number {
    return this.warmCacheLimit;
  }

  isSessionVisible(sessionId: string): boolean {
    return (this.visibleRefCounts.get(sessionId) ?? 0) > 0;
  }

  registerVisible(sessionId: string): () => void {
    const current = this.visibleRefCounts.get(sessionId) ?? 0;
    this.visibleRefCounts.set(sessionId, current + 1);
    if (current === 0) {
      this.markSessionVisible(sessionId);
    }
    let unregistered = false;
    return () => {
      if (unregistered) return;
      unregistered = true;
      const count = (this.visibleRefCounts.get(sessionId) ?? 1) - 1;
      if (count <= 0) {
        this.visibleRefCounts.delete(sessionId);
        this.markSessionInactive(sessionId);
      } else {
        this.visibleRefCounts.set(sessionId, count);
      }
    };
  }

  setVisible(sessionId: string, visible: boolean): void {
    if (visible) {
      const current = this.visibleRefCounts.get(sessionId) ?? 0;
      this.visibleRefCounts.set(sessionId, Math.max(1, current));
      this.markSessionVisible(sessionId);
    } else {
      this.visibleRefCounts.delete(sessionId);
      this.markSessionInactive(sessionId);
    }
  }

  private markSessionVisible(sessionId: string): void {
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    const inst = this.instances.get(sessionId);
    if (inst) {
      if (!inst.unsubscribeOutput) {
        inst.terminal.reset();
        if (inst.session.backendSessionId) {
          inst.unsubscribeOutput = attachScheduledOutputSubscription(inst.session.backendSessionId, inst.terminal);
        }
      }
    }
  }

  private markSessionInactive(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      inst.unsubscribeOutput?.();
      inst.unsubscribeOutput = undefined;
    }
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.inactiveLruSessionIds.push(sessionId);
    this.evictInactiveIfNeeded();
  }

  private evictInactiveIfNeeded(): void {
    while (this.inactiveLruSessionIds.length > this.warmCacheLimit) {
      const oldestSessionId = this.inactiveLruSessionIds.shift();
      if (!oldestSessionId) break;
      this.disposeFrontendInstance(oldestSessionId);
    }
  }

  private disposeInstance(inst: TerminalInstance): void {
    inst.resizeObserver.disconnect();
    inst.unsubscribeOutput?.();
    inst.unsubscribeOutput = undefined;
    for (const d of inst.disposables) d();
    inst.searchAddon.dispose();
    inst.disposeWebgl();
    inst.terminal.dispose();
    inst.element.remove();
  }

  private disposeFrontendInstance(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      this.instances.delete(sessionId);
      this.disposeInstance(inst);
    }
  }

  getInstance(sessionId: string): TerminalInstance | undefined {
    return this.instances.get(sessionId);
  }

  async getOrCreate(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const isVisible = this.isSessionVisible(session.id);
    const existing = this.instances.get(session.id);
    if (existing) {
      existing.session = session;
      existing.active = active;
      existing.onBell = onBell;
      existing.onTitleChange = onTitleChange;

      if (isVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!existing.unsubscribeOutput) {
          existing.terminal.reset();
          if (session.backendSessionId) {
            existing.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, existing.terminal);
          }
        }
      } else {
        if (existing.unsubscribeOutput) {
          existing.unsubscribeOutput();
          existing.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return existing;
    }

    const pending = this.pendingSpawns.get(session.id);
    if (pending) return pending;

    const currentGen = this.spawnGenerations.get(session.id);
    const generation = (currentGen ? currentGen.generation : 0) + 1;
    const activeCount = (currentGen ? currentGen.activeCount : 0) + 1;
    this.spawnGenerations.set(session.id, { generation, activeCount });

    const spawnPromise = this.createInstance(session, active, onBell, onTitleChange);
    this.pendingSpawns.set(session.id, spawnPromise);

    try {
      const instance = await spawnPromise;
      if (this.spawnGenerations.get(session.id)?.generation !== generation) {
        this.disposeInstance(instance);
        return instance;
      }

      this.instances.set(session.id, instance);

      const stillVisible = this.isSessionVisible(session.id);
      if (stillVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!instance.unsubscribeOutput && session.backendSessionId) {
          instance.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, instance.terminal);
        }
      } else {
        if (instance.unsubscribeOutput) {
          instance.unsubscribeOutput();
          instance.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return instance;
    } finally {
      const tracking = this.spawnGenerations.get(session.id);
      if (tracking) {
        tracking.activeCount -= 1;
        if (tracking.activeCount <= 0) {
          this.spawnGenerations.delete(session.id);
        }
      }
      if (this.pendingSpawns.get(session.id) === spawnPromise) {
        this.pendingSpawns.delete(session.id);
      }
    }
  }

  private async createInstance(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const hostElement = document.createElement("div");
    hostElement.className = "terminal-host h-full w-full bg-terminal";
    hostElement.setAttribute("aria-label", `Terminal in ${session.cwd}`);
    Object.assign(hostElement.style, {
      position: "absolute",
      inset: "0px",
      width: "100%",
      height: "100%",
      minWidth: "0px",
      minHeight: "0px",
      overflow: "hidden",
    });

    const [latestNativePrefs, { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor, Unicode11Addon, SearchAddon: SearchAddonConstructor }] =
      await Promise.all([
        Promise.race([
          fetchCachedNativePreferences(),
          new Promise<typeof FALLBACK_PREFERENCES>((resolve) =>
            setTimeout(() => resolve(FALLBACK_PREFERENCES), 200),
          ),
        ]),
        loadTerminalAssets(),
      ]);

    const finalSettings = resolveTerminalSettings(loadTerminalSettings(), latestNativePrefs);

    const terminal = new TerminalConstructor({
      allowProposedApi: false,
      customGlyphs: false,
      convertEol: true,
      cursorBlink: true,
      cursorStyle: finalSettings.cursorStyle ?? "block",
      fontFamily: finalSettings.fontFamily,
      fontSize: finalSettings.fontSize,
      lineHeight: 1.0,
      letterSpacing: 0,
      macOptionIsMeta: finalSettings.macosOptionAsAlt,
      scrollback: finalSettings.scrollback,
      theme: finalSettings.theme,
    });
    const fitAddon = new FitAddonConstructor();
    terminal.loadAddon(fitAddon);
    const searchAddon = new SearchAddonConstructor();
    terminal.loadAddon(searchAddon);
    if (Unicode11Addon) {
      try {
        const unicode11Addon = new Unicode11Addon();
        terminal.loadAddon(unicode11Addon);
        terminal.unicode.activeVersion = "11";
      } catch {
      }
    }
    terminal.open(hostElement);

    let disposeWebgl: () => void = () => undefined;
    void attachWebglRenderer(terminal).then((dispose) => {
      disposeWebgl = dispose;
    });

    let resizeFrame = 0;
    const resize = () => {
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(() => {
        if (hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
        fitAddon.fit();
        const backendSessionId = session.backendSessionId;
        if (!backendSessionId) return;
        void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
      });
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(hostElement);

    const disposables: Array<() => void> = [];

    const dataDisposable = terminal.onData((data) => {
      const backendSessionId = session.backendSessionId;
      if (!backendSessionId) return;
      void writeTerminal({ sessionId: backendSessionId, data }).catch(() => undefined);
    });
    disposables.push(() => dataDisposable.dispose());

    const titleDisposable = terminal.onTitleChange((title) => {
      this.instances.get(session.id)?.onTitleChange?.(title);
    });
    disposables.push(() => titleDisposable.dispose());

    const bellDisposable = terminal.onBell(() => {
      this.instances.get(session.id)?.onBell?.();
    });
    disposables.push(() => bellDisposable.dispose());

    const focusTerminal = () => terminal.focus();
    hostElement.addEventListener("pointerdown", focusTerminal);
    disposables.push(() => hostElement.removeEventListener("pointerdown", focusTerminal));

    let unsubscribeOutput: (() => void) | undefined;
    if (this.isSessionVisible(session.id) && session.backendSessionId) {
      unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, terminal);
    }

    if (!isTauriRuntime()) {
      terminal.writeln("\x1b[1;32mFerryx\x1b[0m  UI preview");
      terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
      terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
    }

    resize();
    if (active) terminal.focus();

    return {
      element: hostElement,
      terminal,
      fitAddon,
      searchAddon,
      disposeWebgl,
      resizeObserver,
      disposables,
      session,
      active,
      onBell,
      onTitleChange,
      unsubscribeOutput,
    };
  }

  updateSession(sessionId: string, session: TerminalSession) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      const prevBackendId = inst.session.backendSessionId;
      inst.session = session;
      const isVisible = this.isSessionVisible(sessionId);
      if (isVisible) {
        if (session.backendSessionId !== prevBackendId) {
          inst.unsubscribeOutput?.();
          inst.unsubscribeOutput = undefined;
          if (session.backendSessionId) {
            inst.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, inst.terminal);
          }
        }
      } else {
        if (inst.unsubscribeOutput) {
          inst.unsubscribeOutput();
          inst.unsubscribeOutput = undefined;
        }
      }
    }
  }

  applyInstanceSettings(sessionId: string, settings: EffectiveTerminalSettings) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  destroy(sessionId: string) {
    const tracking = this.spawnGenerations.get(sessionId);
    if (tracking) {
      tracking.generation += 1;
    }
    this.visibleRefCounts.delete(sessionId);
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.pendingSpawns.delete(sessionId);
    this.disposeFrontendInstance(sessionId);
  }
}

export const terminalHostManager = new TerminalHostManager();

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => {
  let bellHandler: (() => void) | null = null;
  let titleHandler: ((title: string) => void) | null = null;
  let dataHandler: ((data: string) => void) | null = null;
  const terminalWrites: string[] = [];
  const terminalDisposed = vi.fn();
  const terminalReset = vi.fn();
  const searchAddonDisposed = vi.fn();

  class MockTerminal {
    cols = 80;
    rows = 24;
    unicode = { activeVersion: "6" };
    loadAddon = vi.fn();
    open = vi.fn();
    focus = vi.fn();
    dispose = terminalDisposed;
    reset = vi.fn(() => {
      terminalReset();
    });
    write = vi.fn((text: string) => {
      terminalWrites.push(text);
    });
    writeln = vi.fn((text: string) => {
      terminalWrites.push(`${text}\n`);
    });
    onBell(handler: () => void) {
      bellHandler = handler;
      return { dispose: vi.fn() };
    }
    onTitleChange(handler: (title: string) => void) {
      titleHandler = handler;
      return { dispose: vi.fn() };
    }
    onData(handler: (data: string) => void) {
      dataHandler = handler;
      return { dispose: vi.fn() };
    }
  }

  class MockFitAddon {
    fit = vi.fn();
  }

  class MockSearchAddon {
    dispose = searchAddonDisposed;
    findNext = vi.fn();
    findPrevious = vi.fn();
    clearDecorations = vi.fn();
  }

  const outputListeners = new Map<string, Set<(text: string) => void>>();

  return {
    MockTerminal,
    MockFitAddon,
    MockSearchAddon,
    terminalWrites,
    terminalDisposed,
    terminalReset,
    searchAddonDisposed,
    outputListeners,
    triggerBell: () => bellHandler?.(),
    triggerTitleChange: (title: string) => titleHandler?.(title),
    triggerData: (data: string) => dataHandler?.(data),
    emitSessionOutput: (sessionId: string, text: string) => {
      for (const cb of outputListeners.get(sessionId) ?? []) {
        cb(text);
      }
    },
    resetTerminalMocks: () => {
      bellHandler = null;
      titleHandler = null;
      dataHandler = null;
      terminalWrites.length = 0;
      terminalDisposed.mockClear();
      terminalReset.mockClear();
      searchAddonDisposed.mockClear();
      outputListeners.clear();
    },
  };
});

vi.mock("@xterm/xterm", () => ({
  Terminal: mocks.MockTerminal,
}));

vi.mock("@xterm/addon-fit", () => ({
  FitAddon: mocks.MockFitAddon,
}));

vi.mock("@xterm/addon-search", () => ({
  SearchAddon: mocks.MockSearchAddon,
}));

vi.mock("@xterm/addon-unicode11", () => ({
  Unicode11Addon: class MockUnicode11Addon {},
}));

vi.mock("@xterm/addon-webgl", () => ({
  WebglAddon: class MockWebglAddon {
    onContextLoss = vi.fn();
    dispose = vi.fn();
  },
}));

vi.mock("./tauri", async (importOriginal) => {
  const actual = await importOriginal<typeof import("./tauri")>();
  return {
    ...actual,
    isTauriRuntime: vi.fn(() => false),
    resizeTerminal: vi.fn().mockResolvedValue(undefined),
    writeTerminal: vi.fn().mockResolvedValue(undefined),
    spawnTerminal: vi.fn().mockResolvedValue("mock-spawned-id"),
    closeTerminal: vi.fn().mockResolvedValue(undefined),
  };
});

class MockResizeObserver {
  observe = vi.fn();
  unobserve = vi.fn();
  disconnect = vi.fn();
}

vi.stubGlobal("ResizeObserver", MockResizeObserver);

import * as tauriApi from "./tauri";
import { terminalEventBus } from "./terminalEvents";
import { MAX_PENDING_OUTPUT_CHARS, terminalHostManager } from "./terminalHostManager";
import * as terminalSettings from "./terminalSettings";
import type { TerminalSession } from "./types";

const frameCallbacks = new Map<number, FrameRequestCallback>();
let nextFrameId = 1;

function flushAnimationFrames(time = performance.now()) {
  const pending = Array.from(frameCallbacks.values());
  frameCallbacks.clear();
  for (const cb of pending) {
    cb(time);
  }
}

type Deferred<T> = {
  promise: Promise<T>;
  resolve: (value: T) => void;
};

function createDeferred<T>(): Deferred<T> {
  let resolver: ((value: T) => void) | undefined;
  const promise = new Promise<T>((resolve) => {
    resolver = resolve;
  });
  if (!resolver) {
    throw new Error("Deferred resolver was not initialized");
  }
  return { promise, resolve: resolver };
}

function createSession(id = "sess-1", backendSessionId = "backend-1", workspaceId = "ws-1"): TerminalSession {
  return {
    id,
    cwd: `/workspace/${workspaceId}`,
    workspaceId,
    worktree: { wsId: workspaceId, slug: "main" },
    backendSessionId,
    lifecycle: "working",
  };
}

describe("terminalHostManager", () => {
  beforeEach(() => {
    mocks.resetTerminalMocks();
    frameCallbacks.clear();
    nextFrameId = 1;
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockImplementation(() => null);
    vi.stubGlobal("matchMedia", vi.fn(() => ({
      matches: false,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })));
    vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
      const id = nextFrameId++;
      frameCallbacks.set(id, cb);
      return id;
    });
    vi.stubGlobal("cancelAnimationFrame", (id: number) => {
      frameCallbacks.delete(id);
    });
    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementation((sessionId: string, cb: (text: string) => void) => {
      let set = mocks.outputListeners.get(sessionId);
      if (!set) {
        set = new Set();
        mocks.outputListeners.set(sessionId, set);
      }
      set.add(cb);
      return vi.fn(() => {
        set?.delete(cb);
        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
      });
    });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("renders Ferryx branding in non-Tauri preview banner", async () => {
    const session = createSession("sess-banner");
    await terminalHostManager.getOrCreate(session, true);

    const bannerText = mocks.terminalWrites.join("");
    expect(bannerText).toContain("Ferryx");
    expect(bannerText).not.toContain("rorca");
    terminalHostManager.destroy("sess-banner");
  });

  it("fires onBell and onTitleChange exactly once and does not fire stale initial closures when cleared", async () => {
    const session = createSession("sess-events");
    const onBell1 = vi.fn();
    const onTitle1 = vi.fn();

    await terminalHostManager.getOrCreate(session, true, onBell1, onTitle1);

    mocks.triggerBell();
    expect(onBell1).toHaveBeenCalledTimes(1);

    mocks.triggerTitleChange("new title 1");
    expect(onTitle1).toHaveBeenCalledTimes(1);
    expect(onTitle1).toHaveBeenCalledWith("new title 1");

    // Re-register with new callbacks (e.g. component re-render)
    const onBell2 = vi.fn();
    const onTitle2 = vi.fn();
    await terminalHostManager.getOrCreate(session, true, onBell2, onTitle2);

    mocks.triggerBell();
    expect(onBell1).toHaveBeenCalledTimes(1); // Should not fire stale callback
    expect(onBell2).toHaveBeenCalledTimes(1);

    mocks.triggerTitleChange("new title 2");
    expect(onTitle1).toHaveBeenCalledTimes(1); // Should not fire stale callback
    expect(onTitle2).toHaveBeenCalledTimes(1);
    expect(onTitle2).toHaveBeenCalledWith("new title 2");

    // When cleared, neither stale callback should fire
    await terminalHostManager.getOrCreate(session, true, undefined, undefined);
    mocks.triggerBell();
    expect(onBell1).toHaveBeenCalledTimes(1);
    expect(onBell2).toHaveBeenCalledTimes(1);

    mocks.triggerTitleChange("new title 3");
    expect(onTitle1).toHaveBeenCalledTimes(1);
    expect(onTitle2).toHaveBeenCalledTimes(1);

    terminalHostManager.destroy("sess-events");
  });

  it("unsubscribes previous backendSessionId output subscription when backendSessionId changes in updateSession", async () => {
    const session = createSession("sess-update", "backend-old");
    const unreg = terminalHostManager.registerVisible("sess-update");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;
    mocks.emitSessionOutput("backend-old", "hello old");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello old");

    mocks.terminalWrites.length = 0;
    const updatedSession = createSession("sess-update", "backend-new");
    terminalHostManager.updateSession("sess-update", updatedSession);

    // Old backend session output must NOT be written anymore
    mocks.emitSessionOutput("backend-old", "old after update");
    flushAnimationFrames();
    expect(mocks.terminalWrites).not.toContain("old after update");

    // New backend session output MUST be written
    mocks.emitSessionOutput("backend-new", "hello new");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello new");

    unreg();
    terminalHostManager.destroy("sess-update");
  });

  it("batches same-frame output writes at animation-frame cadence into a single ordered terminal write", async () => {
    const session = createSession("sess-batched", "backend-batch");
    const unreg = terminalHostManager.registerVisible("sess-batched");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-batch", "chunk1-");
    mocks.emitSessionOutput("backend-batch", "chunk2-");
    mocks.emitSessionOutput("backend-batch", "chunk3");

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    // Flush animation frame
    flushAnimationFrames();

    // Exactly one write call with all 3 chunks in original order
    expect(mocks.terminalWrites).toEqual(["chunk1-chunk2-chunk3"]);

    unreg();
    terminalHostManager.destroy("sess-batched");
  });

  it("cancels pending batched output and prevents writes after destroy or updateSession rebinding", async () => {
    // 1. Teardown via destroy
    const session1 = createSession("sess-teardown-1", "backend-td-1");
    const unreg1 = terminalHostManager.registerVisible("sess-teardown-1");
    await terminalHostManager.getOrCreate(session1, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-1", "pending before destroy");
    unreg1();
    terminalHostManager.destroy("sess-teardown-1");

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Teardown via updateSession rebinding
    const session2 = createSession("sess-teardown-2", "backend-td-old");
    const unreg2 = terminalHostManager.registerVisible("sess-teardown-2");
    await terminalHostManager.getOrCreate(session2, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-old", "pending before rebind");
    const session2Updated = createSession("sess-teardown-2", "backend-td-new");
    terminalHostManager.updateSession("sess-teardown-2", session2Updated);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // New backend emits and flushes normally
    mocks.emitSessionOutput("backend-td-new", "live new");
    expect(mocks.terminalWrites).toHaveLength(0);
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["live new"]);

    unreg2();
    terminalHostManager.destroy("sess-teardown-2");
  });

  it("batches outputs per session independently without cross-session mixing", async () => {
    const session1 = createSession("sess-mix-1", "backend-mix-1");
    const session2 = createSession("sess-mix-2", "backend-mix-2");

    const unreg1 = terminalHostManager.registerVisible("sess-mix-1");
    const unreg2 = terminalHostManager.registerVisible("sess-mix-2");

    await terminalHostManager.getOrCreate(session1, true);
    await terminalHostManager.getOrCreate(session2, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-mix-1", "s1-a");
    mocks.emitSessionOutput("backend-mix-2", "s2-a");
    mocks.emitSessionOutput("backend-mix-1", "s1-b");
    mocks.emitSessionOutput("backend-mix-2", "s2-b");

    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();

    expect(mocks.terminalWrites).toEqual(["s1-as1-b", "s2-as2-b"]);

    unreg1();
    unreg2();
    terminalHostManager.destroy("sess-mix-1");
    terminalHostManager.destroy("sess-mix-2");
  });

  it("maintains replay-before-live ordering on initial subscription", async () => {
    const session = createSession("sess-replay", "backend-replay");
    const unreg = terminalHostManager.registerVisible("sess-replay");

    // Simulate backlog replay synchronously during subscribeOutput
    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementationOnce((sessionId: string, cb: (text: string) => void) => {
      let set = mocks.outputListeners.get(sessionId);
      if (!set) {
        set = new Set();
        mocks.outputListeners.set(sessionId, set);
      }
      set.add(cb);
      cb("replay-chunk-");
      return vi.fn(() => {
        set?.delete(cb);
        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
      });
    });

    await terminalHostManager.getOrCreate(session, true);
    mocks.emitSessionOutput("backend-replay", "live-chunk");

    // Clear preview banner writes
    mocks.terminalWrites.length = 0;

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["replay-chunk-live-chunk"]);

    unreg();
    terminalHostManager.destroy("sess-replay");
  });

  it("integrates search addon into terminal instance and disposes it on destroy", async () => {
    const session = createSession("sess-search");
    const unreg = terminalHostManager.registerVisible("sess-search");
    const instance = await terminalHostManager.getOrCreate(session, true);

    expect(instance.searchAddon).toBeDefined();
    expect(instance.terminal.loadAddon).toHaveBeenCalledWith(instance.searchAddon);

    unreg();
    terminalHostManager.destroy("sess-search");
    expect(mocks.searchAddonDisposed).toHaveBeenCalledTimes(1);
  });

  it("disposes stale renderer and does not resurrect instances or LRU when destroy occurs during pending creation", async () => {
    const deferredPrefs = createDeferred<typeof terminalSettings.FALLBACK_PREFERENCES>();
    const prefsSpy = vi.spyOn(terminalSettings, "fetchCachedNativePreferences").mockImplementation(() => deferredPrefs.promise);

    const session = createSession("sess-race-destroy", "backend-race-destroy");

    try {
      // 1. Initiate getOrCreate while preference resolution (renderer creation) is pending
      const pendingCreation = terminalHostManager.getOrCreate(session, true);

      // 2. Destroy session while creation is awaiting
      terminalHostManager.destroy("sess-race-destroy");

      // Verify not yet in instances
      expect(terminalHostManager.getInstance("sess-race-destroy")).toBeUndefined();

      // 3. Resolve the delayed creation promise
      deferredPrefs.resolve(terminalSettings.FALLBACK_PREFERENCES);
      const staleInstance = await pendingCreation;

      // 4. Stale instance must be disposed and not populate instances or cache
      expect(terminalHostManager.getInstance("sess-race-destroy")).toBeUndefined();
      expect(mocks.terminalDisposed).toHaveBeenCalledTimes(1);
      expect(mocks.searchAddonDisposed).toHaveBeenCalledTimes(1);

      // 5. Subsequent legitimate getOrCreate for the same session ID succeeds with a fresh instance
      prefsSpy.mockResolvedValue(terminalSettings.FALLBACK_PREFERENCES);
      const freshInstance = await terminalHostManager.getOrCreate(session, true);
      expect(freshInstance).toBeDefined();
      expect(freshInstance).not.toBe(staleInstance);
      expect(terminalHostManager.getInstance("sess-race-destroy")).toBe(freshInstance);
    } finally {
      prefsSpy.mockRestore();
      terminalHostManager.destroy("sess-race-destroy");
    }
  });

  it("handles overlapping destroy and new getOrCreate before stale creation resolves without erasing newer pending creation", async () => {
    const deferredPrefs1 = createDeferred<typeof terminalSettings.FALLBACK_PREFERENCES>();
    const deferredPrefs2 = createDeferred<typeof terminalSettings.FALLBACK_PREFERENCES>();

    const prefsSpy = vi.spyOn(terminalSettings, "fetchCachedNativePreferences")
      .mockImplementationOnce(() => deferredPrefs1.promise)
      .mockImplementationOnce(() => deferredPrefs2.promise);

    const session = createSession("sess-overlap-destroy", "backend-overlap-destroy");

    try {
      // 1. Initiate first getOrCreate
      const firstCreation = terminalHostManager.getOrCreate(session, true);

      // 2. Destroy session while first creation is pending
      terminalHostManager.destroy("sess-overlap-destroy");

      // 3. Initiate second getOrCreate before first creation resolves
      const secondCreation = terminalHostManager.getOrCreate(session, true);

      // 4. Resolve first (stale) creation
      deferredPrefs1.resolve(terminalSettings.FALLBACK_PREFERENCES);
      const staleInstance = await firstCreation;

      // Stale instance must be disposed, not in instances
      expect(terminalHostManager.getInstance("sess-overlap-destroy")).toBeUndefined();
      expect(mocks.terminalDisposed).toHaveBeenCalled();

      // 5. Resolve second (legitimate) creation
      deferredPrefs2.resolve(terminalSettings.FALLBACK_PREFERENCES);
      const newInstance = await secondCreation;

      expect(newInstance).toBeDefined();
      expect(newInstance).not.toBe(staleInstance);
      expect(terminalHostManager.getInstance("sess-overlap-destroy")).toBe(newInstance);
    } finally {
      prefsSpy.mockRestore();
      terminalHostManager.destroy("sess-overlap-destroy");
    }
  });

  it("evicts oldest inactive instance when exceeding warm budget while preserving all visible split instances and backend sessions", async () => {
    // Warm capacity = 2 inactive instances
    terminalHostManager.setWarmCacheLimit(2);

    // 1. Two visible split instances
    const visSession1 = createSession("sess-vis-1", "backend-vis-1");
    const visSession2 = createSession("sess-vis-2", "backend-vis-2");

    const unregVis1 = terminalHostManager.registerVisible("sess-vis-1");
    const unregVis2 = terminalHostManager.registerVisible("sess-vis-2");

    await terminalHostManager.getOrCreate(visSession1, true);
    await terminalHostManager.getOrCreate(visSession2, false);

    expect(terminalHostManager.getInstance("sess-vis-1")).toBeDefined();
    expect(terminalHostManager.getInstance("sess-vis-2")).toBeDefined();

    // 2. Add 3 inactive sessions in sequence (exceeding warm budget of 2)
    const inact1 = createSession("sess-inact-1", "backend-inact-1");
    const inact2 = createSession("sess-inact-2", "backend-inact-2");
    const inact3 = createSession("sess-inact-3", "backend-inact-3");

    await terminalHostManager.getOrCreate(inact1, false);
    await terminalHostManager.getOrCreate(inact2, false);
    await terminalHostManager.getOrCreate(inact3, false);

    // 3. Oldest inactive frontend renderer must be disposed and evicted
    expect(terminalHostManager.getInstance("sess-inact-1")).toBeUndefined();
    expect(mocks.terminalDisposed).toHaveBeenCalled();

    // 4. Visible split instances MUST remain pinned and not evicted
    expect(terminalHostManager.getInstance("sess-vis-1")).toBeDefined();
    expect(terminalHostManager.getInstance("sess-vis-2")).toBeDefined();

    // 5. Inactive instances within warm budget (2 and 3) remain warm
    expect(terminalHostManager.getInstance("sess-inact-2")).toBeDefined();
    expect(terminalHostManager.getInstance("sess-inact-3")).toBeDefined();

    // 6. Backend session record for inact1 is NOT closed or destroyed
    expect(inact1.backendSessionId).toBe("backend-inact-1");

    unregVis1();
    unregVis2();
    terminalHostManager.destroy("sess-vis-1");
    terminalHostManager.destroy("sess-vis-2");
    terminalHostManager.destroy("sess-inact-2");
    terminalHostManager.destroy("sess-inact-3");
  });

  it("suspends inactive output without background writes and replays in correct order upon reactivation", async () => {
    const session = createSession("sess-suspend", "backend-suspend");
    const unreg = terminalHostManager.registerVisible("sess-suspend");
    await terminalHostManager.getOrCreate(session, true);

    // Initial output while visible
    mocks.terminalWrites.length = 0;
    mocks.emitSessionOutput("backend-suspend", "vis-1");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["vis-1"]);

    // Unmount / suspend session
    unreg();

    // Clear write logs
    mocks.terminalWrites.length = 0;

    // Output emitted while inactive: TerminalEventBus processes it, but xterm does NOT write
    const backlogChunks = ["vis-1"];
    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementation((sessionId: string, cb: (text: string) => void) => {
      let set = mocks.outputListeners.get(sessionId);
      if (!set) {
        set = new Set();
        mocks.outputListeners.set(sessionId, set);
      }
      set.add(cb);
      // Replay full backlog
      cb(backlogChunks.join(""));
      return vi.fn(() => {
        set?.delete(cb);
        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
      });
    });

    mocks.emitSessionOutput("backend-suspend", "inact-2");
    backlogChunks.push("inact-2");
    flushAnimationFrames();

    // No direct background writes while suspended
    expect(mocks.terminalWrites).toHaveLength(0);

    // Reactivate session
    const unreg2 = terminalHostManager.registerVisible("sess-suspend");
    await terminalHostManager.getOrCreate(session, true);

    // Terminal must be reset before replaying backlog so stale output is not duplicated
    expect(mocks.terminalReset).toHaveBeenCalled();

    flushAnimationFrames();
    // Replay delivers complete backlog in order
    expect(mocks.terminalWrites).toContain("vis-1inact-2");

    unreg2();
    terminalHostManager.destroy("sess-suspend");
  });

  it("synchronously flushes pending output when accumulated characters reach or exceed MAX_PENDING_OUTPUT_CHARS before rAF", async () => {
    const session = createSession("sess-cap", "backend-cap");
    const unreg = terminalHostManager.registerVisible("sess-cap");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    const halfCap = "A".repeat(MAX_PENDING_OUTPUT_CHARS / 2);
    const exceedCap = "B".repeat(MAX_PENDING_OUTPUT_CHARS / 2 + 10);
    const trailingChunk = "C".repeat(50);

    // 1. Below cap: queued without immediate write
    mocks.emitSessionOutput("backend-cap", halfCap);
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Reaching/exceeding cap: synchronously flushes accumulated batch immediately before rAF
    mocks.emitSessionOutput("backend-cap", exceedCap);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 3. New chunk arriving after flush is held for next rAF
    mocks.emitSessionOutput("backend-cap", trailingChunk);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 4. On rAF flush, trailing chunk is written in ordered sequence
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap, trailingChunk]);

    unreg();
    terminalHostManager.destroy("sess-cap");
  });

  it("supports 100 simulated live sessions across five workspaces with visible sessions pinned and inactive renderers bounded by warm limit", async () => {
    const originalLimit = terminalHostManager.getWarmCacheLimit();
    const targetWarmLimit = 3;
    terminalHostManager.setWarmCacheLimit(targetWarmLimit);
    expect(terminalHostManager.getWarmCacheLimit()).toBe(targetWarmLimit);

    const closeTerminalSpy = vi.spyOn(tauriApi, "closeTerminal");
    const spawnTerminalSpy = vi.spyOn(tauriApi, "spawnTerminal");

    const totalWorkspaces = 5;
    const sessionsPerWorkspace = 20;
    const allSessions: TerminalSession[] = [];

    for (let wsIndex = 0; wsIndex < totalWorkspaces; wsIndex++) {
      const wsId = `ws-${wsIndex}`;
      for (let sIndex = 0; sIndex < sessionsPerWorkspace; sIndex++) {
        const id = `${wsId}-sess-${sIndex}`;
        allSessions.push(createSession(id, `backend-${id}`, wsId));
      }
    }
    expect(allSessions).toHaveLength(100);

    // Explicit visible set across multiple workspaces (one visible per workspace)
    const visibleSessionIds = [
      "ws-0-sess-0",
      "ws-1-sess-4",
      "ws-2-sess-8",
      "ws-3-sess-12",
      "ws-4-sess-16",
    ];

    const unregHandles = new Map<string, () => void>();
    for (const visId of visibleSessionIds) {
      unregHandles.set(visId, terminalHostManager.registerVisible(visId));
    }

    // Register a second visible mount for one session to verify reference-count behavior
    const multiRefSessionId = visibleSessionIds[0]!;
    const unregSecondMount = terminalHostManager.registerVisible(multiRefSessionId);

    try {
      // Create all 100 sessions sequentially
      for (const session of allSessions) {
        const isVisible = terminalHostManager.isSessionVisible(session.id);
        await terminalHostManager.getOrCreate(session, isVisible);
      }

      // 1. Visible renderer instances remain pinned and alive
      for (const visId of visibleSessionIds) {
        expect(terminalHostManager.isSessionVisible(visId)).toBe(true);
        const inst = terminalHostManager.getInstance(visId);
        expect(inst).toBeDefined();
        expect(inst?.session.id).toBe(visId);
      }

      // 2. Count alive instances: visible vs inactive
      const aliveInstances = allSessions.filter((s) => terminalHostManager.getInstance(s.id) !== undefined);
      const aliveVisible = aliveInstances.filter((s) => terminalHostManager.isSessionVisible(s.id));
      const aliveInactive = aliveInstances.filter((s) => !terminalHostManager.isSessionVisible(s.id));

      expect(aliveVisible).toHaveLength(visibleSessionIds.length);
      expect(aliveInactive.length).toBeLessThanOrEqual(terminalHostManager.getWarmCacheLimit());
      expect(aliveInactive.length).toBe(targetWarmLimit);
      expect(aliveInstances).toHaveLength(visibleSessionIds.length + targetWarmLimit);

      // 3. All 100 backendSessionId values and session objects remain intact
      for (const session of allSessions) {
        expect(session.backendSessionId).toBe(`backend-${session.id}`);
        expect(session.lifecycle).toBe("working");
        expect(session.workspaceId).toMatch(/^ws-\d+$/);
      }

      // 4. No backend close, spawn, or IPC APIs were called by frontend manager eviction
      expect(closeTerminalSpy).not.toHaveBeenCalled();
      expect(spawnTerminalSpy).not.toHaveBeenCalled();

      // 5. Oldest inactive frontend renderers were disposed
      const allInactiveSessions = allSessions.filter((s) => !visibleSessionIds.includes(s.id));
      const expectedWarmInactive = allInactiveSessions.slice(-targetWarmLimit);
      const expectedDisposedInactive = allInactiveSessions.slice(0, -targetWarmLimit);

      expect(expectedDisposedInactive.length).toBe(95 - targetWarmLimit);
      for (const session of expectedDisposedInactive) {
        expect(terminalHostManager.getInstance(session.id)).toBeUndefined();
      }
      for (const session of expectedWarmInactive) {
        expect(terminalHostManager.getInstance(session.id)).toBeDefined();
      }

      // 6. Verify reference-count behavior:
      // Release first mount handle of multiRefSessionId
      const unregFirstMount = unregHandles.get(multiRefSessionId)!;
      unregFirstMount();

      // Proving it remains pinned until the final handle releases
      expect(terminalHostManager.isSessionVisible(multiRefSessionId)).toBe(true);
      expect(terminalHostManager.getInstance(multiRefSessionId)).toBeDefined();

      // Release the second (final) mount handle
      unregSecondMount();
      expect(terminalHostManager.isSessionVisible(multiRefSessionId)).toBe(false);

      // Now multiRefSessionId transitioned to inactive and joined warm LRU cache
      const inactiveAfterRelease = allSessions.filter(
        (s) => !terminalHostManager.isSessionVisible(s.id) && terminalHostManager.getInstance(s.id) !== undefined,
      );
      expect(inactiveAfterRelease.length).toBeLessThanOrEqual(terminalHostManager.getWarmCacheLimit());
    } finally {
      for (const unreg of unregHandles.values()) {
        unreg();
      }
      for (const session of allSessions) {
        terminalHostManager.destroy(session.id);
      }
      terminalHostManager.setWarmCacheLimit(originalLimit);
      closeTerminalSpy.mockRestore();
      spawnTerminalSpy.mockRestore();
    }
  });
});

