const fs = require("fs");
function countPureLoc(filePath) {
  const content = fs.readFileSync(filePath, "utf8");
  let stripped = content.replace(/\/\*[\s\S]*?\*\//g, "");
  const lines = stripped.split("\n").map(l => l.replace(/\/\/.*$/, "").trim()).filter(l => l.length > 0);
  return lines.length;
}

