node -e '
const fs = require("fs");
function countPureLoc(filePath) {
  const content = fs.readFileSync(filePath, "utf8");
  let stripped = content.replace(/\/\*[\s\S]*?\*\//g, "");
  const lines = stripped.split("\n").map(l => l.replace(/\/\/.*$/, "").trim()).filter(l => l.length > 0);
  return lines.length;
}

const files = [
  "ui/src/lib/terminalHostManager.ts",
  "ui/src/lib/terminalInstanceFactory.ts",
  "ui/src/lib/terminalOutputScheduler.ts"
];

for (const f of files) {
  const total = fs.readFileSync(f, "utf8").split("\n").length;
  const pure = countPureLoc(f);
  console.log(`${f} -> total lines: ${total}, nonblank/noncomment LOC: ${pure} (<= 250: ${pure <= 250})`);
}
'
